func TestSimpleVideoGraph_Null(t *testing.T) {
	ctx := context.Background()
	g, err := NewSimpleVideoGraph(ctx, "null", SimpleVideoGraphConfig{
		Width:       320,
		Height:      240,
		PixelFormat: astiav.PixelFormatYuv420P,
		TimeBase:    astiav.NewRational(1, 30),
	})
	require.NoError(t, err)
	defer g.Close()

	f := astiav.AllocFrame()
	defer f.Free()
	f.SetWidth(320)
	f.SetHeight(240)
	f.SetPixelFormat(astiav.PixelFormatYuv420P)
	require.NoError(t, f.AllocBuffer(32))

	frames, err := g.ProcessFrame(ctx, f)
	require.NoError(t, err)
	require.Len(t, frames, 1)
	testifyassert.Equal(t, 320, frames[0].Width())
	testifyassert.Equal(t, 240, frames[0].Height())
}

