func TestSimpleGraph_AddFrameGetFrame(t *testing.T) {
	ctx := context.Background()
	g, err := NewSimpleVideoGraph(ctx, "null", SimpleVideoGraphConfig{
		Width:       320,
		Height:      240,
		PixelFormat: astiav.PixelFormatYuv420P,
		TimeBase:    astiav.NewRational(1, 30),
	})
	require.NoError(t, err)
	defer g.Close()

	f := astiav.AllocFrame()
	defer f.Free()
	f.SetWidth(320)
	f.SetHeight(240)
	f.SetPixelFormat(astiav.PixelFormatYuv420P)
	require.NoError(t, f.AllocBuffer(32))

	err = g.AddFrame(0, f, astiav.NewBuffersrcFlags(astiav.BuffersrcFlagKeepRef))
	require.NoError(t, err)

	out := astiav.AllocFrame()
	defer out.Free()
	err = g.GetFrame(0, out, astiav.NewBuffersinkFlags())
	require.NoError(t, err)
	testifyassert.Equal(t, 320, out.Width())
	testifyassert.Equal(t, 240, out.Height())
}

